 "content": "def transform(grid):
    out = [row[:] for row in grid]
    ones = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 1]
    twos = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 2]
    if len(ones) != 1 or len(twos) != 1:
        raise ValueError("expected one 1 and one 2")
    r, c = ones[0]
    tr, tc = twos[0]
    dr = 1 if tr > r else -1 if tr < r else 0
    dc = 1 if tc > c else -1 if tc < c else 0
    diagonal = min(abs(tr - r), abs(tc - c))
    for _ in range(diagonal):
        r += dr
        c += dc
        if (r, c) != (tr, tc):
            out[r][c] = 3
    while r != tr or c != tc:
        if r != tr:
            r += dr
        else:
            c += dc
        if (r, c) != (tr, tc):
            out[r][c] = 3
    return out
